# ---------------- BUILD ----------------
used_ids = {}
out = []
errors = []
for e in E:
    v = V.get(e["slug"])
    if not v or not v.get("videoId"):
        errors.append(f"NO VIDEO: {e['slug']}")
        continue
    vid = v["videoId"]
    if vid in used_ids:
        errors.append(f"DUPLICATE VIDEO {vid}: {e['slug']} vs {used_ids[vid]}")
        continue
    used_ids[vid] = e["slug"]
    # validate enums
    if e["muscle"] not in MUSCLES: errors.append(f"BAD MUSCLE {e['slug']}: {e['muscle']}")
    for s in e["secondary"]:
        if s not in MUSCLES: errors.append(f"BAD SECONDARY {e['slug']}: {s}")
    if e["equipment"] not in EQUIP: errors.append(f"BAD EQUIP {e['slug']}")
    if e["category"] not in CATS: errors.append(f"BAD CAT {e['slug']}")
    if e["difficulty"] not in DIFF: errors.append(f"BAD DIFF {e['slug']}")
    for d in e["disciplines"]:
        if d not in DISC: errors.append(f"BAD DISC {e['slug']}: {d}")
    if e["core"] and not e["desc"]: errors.append(f"MISSING DESC {e['slug']}")
    if e["core"] and not e["tips"]: errors.append(f"MISSING TIPS {e['slug']}")
    if not e["core"] and (e["desc"] or e["tips"]): errors.append(f"EXTRA TEXT {e['slug']}")
    obj = {
        "en": e["en"], "fa": e["fa"], "name": f'{e["fa"]} ({e["en"]})',
        "muscle": e["muscle"], "secondary": e["secondary"],
        "equipment": e["equipment"], "category": e["category"], "pattern": e["pattern"],
        "difficulty": e["difficulty"], "core": e["core"], "disciplines": e["disciplines"],
        "ytVideoId": vid, "ytTitle": v["title"], "ytChannel": v["channel"],
        "description": e["desc"], "tips": e["tips"],
    }
    out.append(obj)

if errors:
    print("ERRORS:")
    for x in errors: print(" -", x)
    sys.exit(1)

path = "/home/z/my-project/scripts/exercise-research/groupC-bodyweight.json"
json.dump(out, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
core_n = sum(1 for o in out if o["core"])
from collections import Counter
print(f"WROTE {path}: total={len(out)} core={core_n} unique_videos={len(used_ids)}")
print("equipment:", dict(Counter(o["equipment"] for o in out)))
print("category:", dict(Counter(o["category"] for o in out)))
print("difficulty:", dict(Counter(o["difficulty"] for o in out)))
print("muscle:", dict(Counter(o["muscle"] for o in out)))
